import java.util.Scanner;

public class Main {
    static final int MODULUS = 1000000007;
    static int mod_value = MODULUS;
    static int[] P = new int[1000001];

    static int add_mod(int a, int b) {
        int res = a + b;
        return res < mod_value ? res : res - mod_value;
    }

    static int multiply_mod(int a, int b) {
        long res = (long) a * b;
        return (int) (res % mod_value);
    }

    static int fast_pow(int base, int exp) {
        int res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = multiply_mod(res, base);
            }
            base = multiply_mod(base, base);
            exp >>= 1;
        }
        return res;
    }

    static int compute_beb(int a, int m) {
        for (int i = 0; i < P.length; i++) {
            P[i] = -1;
        }
        int s = (int) Math.sqrt(m);
        mod_value = m;
        int r = a % m;
        int d = fast_pow(a, m - 2);
        for (int i = 0; i <= s; ++i) {
            if (P[r] == -1) P[r] = i;
            r = multiply_mod(r, d);
            if (r == 1) {
                mod_value = MODULUS;
                return i + 1;
            }
        }
        d = fast_pow(a, s);
        r = d;
        for (int i = 1; i <= s; ++i) {
            if (P[r] > -1) {
                mod_value = MODULUS;
                return s * i + P[r];
            }
            r = multiply_mod(r, d);
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 1) {
            System.out.println(fast_pow(p, p));
        } else if (k == 0) {
            System.out.println(fast_pow(p, p - 1));
        } else {
            int beb = compute_beb(k, p);
            System.out.println(fast_pow(p, (p - 1) / beb));
        }
        sc.close();
    }
}
